### Forward Refs to HugeIcons React SVG Elements

Source: https://context7.com/hugeicons/hugeicons-react/llms.txt

This example demonstrates how to use React's `useRef` hook to get a direct reference to the underlying SVG element of a HugeIcons React component. This allows for direct DOM manipulation, such as accessing dimensions via `getBoundingClientRect` or applying inline styles for programmatic animations. It's useful for integrating with other DOM-dependent libraries or performing complex UI interactions.

```jsx
import { useRef, useEffect } from "react";
import { Home01Icon } from "hugeicons-react";

function RefExample() {
  const iconRef = useRef(null);

  useEffect(() => {
    if (iconRef.current) {
      // Direct SVG element access
      console.log("Icon dimensions:", iconRef.current.getBoundingClientRect());

      // Programmatic animation
      iconRef.current.style.transition = "transform 0.5s";
      iconRef.current.style.transform = "scale(1.2)";
    }
  }, []);

  return <Home01Icon ref={iconRef} size={48} />;
}

// Tooltip example with ref
function IconWithTooltip() {
  const iconRef = useRef(null);

  const showTooltip = () => {
    const rect = iconRef.current.getBoundingClientRect();
    // Position tooltip based on icon location
    console.log("Show tooltip at:", rect.x, rect.y);
  };

  return (
    <Home01Icon
      ref={iconRef}
      onMouseEnter={showTooltip}
      size={32}
    />
  );
}

```

