### Design System Integration with HugeIcons (JSX)

Source: https://context7.com/hugeicons/hugeicons-react/llms.txt

Illustrates how to integrate 'hugeicons-react' into a design system by creating themed icon components and icon buttons. This approach allows for consistent styling across an application by defining design tokens for colors, sizes, and stroke weights, which are then applied to the icon components.

```jsx
import { Home01Icon, MarketingIcon, UserIcon } from "hugeicons-react";

// Design tokens
const DESIGN_SYSTEM = {
  colors: {
    primary: "#4A90E2",
    secondary: "#7B8794",
    success: "#2ECC71",
    danger: "#E74C3C",
    warning: "#F39C12"
  },
  sizes: {
    xs: 16,
    sm: 20,
    md: 24,
    lg: 32,
    xl: 48
  },
  strokeWeights: {
    thin: 1,
    regular: 1.5,
    medium: 2,
    bold: 3
  }
};

// Themed icon component
function ThemedIcon({ 
  icon: Icon,
  colorTheme = "primary",
  size = "md",
  weight = "regular",
  ...props
}) {
  return (
    <Icon
      size={DESIGN_SYSTEM.sizes[size]}
      color={DESIGN_SYSTEM.colors[colorTheme]}
      strokeWidth={DESIGN_SYSTEM.strokeWeights[weight]}
      {...props}
    />
  );
}

// Usage in application
function Dashboard() {
  return (
    <div>
      <ThemedIcon
        icon={Home01Icon}
        colorTheme="primary"
        size="lg"
      />
      <ThemedIcon
        icon={UserIcon}
        colorTheme="secondary"
        size="md"
      />
      <ThemedIcon
        icon={MarketingIcon}
        colorTheme="success"
        size="sm"
        weight="bold"
      />
    </div>
  );
}

// Icon button component
function IconButton({
  icon: Icon,
  variant = "primary",
  onClick,
  disabled = false
}) {
  const styles = {
    padding: "12px",
    border: "none",
    borderRadius: "8px",
    background: disabled
      ? "#E0E0E0"
      : DESIGN_SYSTEM.colors[variant],
    cursor: disabled ? "not-allowed" : "pointer",
    opacity: disabled ? 0.5 : 1,
    transition: "all 0.2s"
  };

  return (
    <button style={styles} onClick={onClick} disabled={disabled}>
      <Icon
        size={DESIGN_SYSTEM.sizes.md}
        color="#FFFFFF"
      />
    </button>
  );
}

// Navigation menu example
function Navigation() {
  const menuItems = [
    { icon: Home01Icon, label: "Home", href: "/" },
    { icon: UserIcon, label: "Profile", href: "/profile" },
    { icon: MarketingIcon, label: "Marketing", href: "/marketing" }
  ];

  return (
    <nav style={{ display: "flex", gap: "16px" }}>
      {menuItems.map(item => (
        <a
          key={item.label}
          href={item.href}
          style={{
            display: "flex",
            alignItems: "center",
            gap: "8px",
            textDecoration: "none",
            color: DESIGN_SYSTEM.colors.primary
          }}>
          <item.icon size={DESIGN_SYSTEM.sizes.md} />
          <span>{item.label}</span>
        </a>
      ))}
    </nav>
  );
}
