### TypeScript Integration with HugeIcons (TSX)

Source: https://context7.com/hugeicons/hugeicons-react/llms.txt

Showcases how to leverage TypeScript for type-safe icon usage with 'hugeicons-react'. It includes a typed icon wrapper component and a generic icon component that accepts `HugeiconsProps` for type checking and props spreading. This ensures correct prop usage and reduces potential runtime errors.

```tsx
import {
  Home01Icon,
  HugeiconsProps,
  HugeiconsIcon
} from "hugeicons-react";
import { FC } from "react";

// Typed icon wrapper component
interface IconWrapperProps {
  icon: HugeiconsIcon;
  size?: number;
  variant?: "primary" | "secondary" | "danger";
}

const VARIANT_COLORS = {
  primary: "#4A90E2",
  secondary: "#7B8794",
  danger: "#E74C3C"
};

const IconWrapper: FC<IconWrapperProps> = ({ 
  icon: Icon,
  size = 24,
  variant = "primary"
}) => {
  return (
    <Icon
      size={size}
      color={VARIANT_COLORS[variant]}
    />
  );
};

// Usage with type checking
function App() {
  return (
    <div>
      <IconWrapper icon={Home01Icon} variant="primary" size={32} />
      {/* TypeScript error: invalid variant */}
      {/* <IconWrapper icon={Home01Icon} variant="invalid" /> */}
    </div>
  );
}

// Generic icon component with props spreading
interface CustomIconProps extends HugeiconsProps {
  label?: string;
}

const LabeledIcon: FC<CustomIconProps> = ({ 
  label,
  ...iconProps
}) => {
  return (
    <div style={{ display: "flex", alignItems: "center", gap: "8px" }}>
      <Home01Icon {...iconProps} />
      {label && <span>{label}</span>}
    </div>
  );
};

// Type-safe usage
<LabeledIcon
  label="Dashboard"
  size={24}
  color="#4A90E2"
  strokeWidth={2}
/>
