### Create Custom Icon Components with hugeicons-react

Source: https://context7.com/hugeicons/hugeicons-react/llms.txt

This TypeScript example demonstrates how to create a custom icon component using the `createHugeiconComponent` factory function provided by the `hugeicons-react` library. It involves defining the SVG structure as an array of elements and their attributes, then using the factory to generate a reusable React component that can be styled and sized like any other icon from the library.

```tsx
import createHugeiconComponent, {
  IconSvgObject
} from "hugeicons-react";

// Define SVG structure as array of [element, attributes]
const customIconSvg: IconSvgObject = [
  [
    "path",
    {
      id: "path1",
      d: "M12 2L2 7l10 5 10-5-10-5z",
      stroke: "currentColor",
      fill: "none"
    }
  ],
  [
    "path",
    {
      id: "path2",
      d: "M2 17l10 5 10-5M2 12l10 5 10-5",
      stroke: "currentColor",
      fill: "none"
    }
  ]
];

// Create the component
const CustomStackIcon = createHugeiconComponent(
  "CustomStack",
  customIconSvg
);

// Use like any other icon
function App() {
  return (
    <div>
      <CustomStackIcon size={48} color="#4A90E2" />
      <CustomStackIcon size={32} strokeWidth={2} />
    </div>
  );
}

export default CustomStackIcon;

```

